--

CREATE FUNCTION public.deny_modify_domain_event_log() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  RAISE EXCEPTION 'DomainEventLog is append-only; % is not permitted', TG_OP;
END;
$$;


--
-- Name: evidence_purge_enabled(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.evidence_purge_enabled() RETURNS boolean
    LANGUAGE sql STABLE
    AS $$
  SELECT coalesce(current_setting('app.evidence_purge', true), '') = 'on'
$$;


--
-- Name: evidence_row_changed(jsonb, jsonb, text[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.evidence_row_changed(old_row jsonb, new_row jsonb, allowed text[]) RETURNS boolean
    LANGUAGE sql IMMUTABLE
    AS $$
  SELECT (old_row - allowed) IS DISTINCT FROM (new_row - allowed)
$$;


--
-- Name: guard_cash_movement(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.guard_cash_movement() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF evidence_purge_enabled() THEN RETURN COALESCE(NEW, OLD); END IF;
  RAISE EXCEPTION 'CashMovement % is posted drawer evidence and cannot be %; record a linked correction instead',
    OLD.id, lower(TG_OP) USING ERRCODE = 'integrity_constraint_violation';
END $$;


--
-- Name: guard_cash_movement_insert(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.guard_cash_movement_insert() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE p record;
BEGIN
  IF evidence_purge_enabled() THEN RETURN NEW; END IF;
  IF NOT EXISTS (SELECT 1 FROM "CashSession" s WHERE s.id = NEW."cashSessionId" AND s."organizationId" = NEW."organizationId" AND s.status = 'open') THEN
    RAISE EXCEPTION 'Drawer movements can only be recorded on an open shift of the same organization' USING ERRCODE = 'integrity_constraint_violation';
  END IF;
  IF NEW."paymentId" IS NOT NULL THEN
    SELECT "organizationId", "cashSessionId", "paymentMethod", direction, "refundOfId" INTO p FROM "Payment" WHERE id = NEW."paymentId";
    IF NOT FOUND OR p."organizationId" <> NEW."organizationId" THEN
      RAISE EXCEPTION 'Drawer movement must reference a payment of the same organization' USING ERRCODE = 'integrity_constraint_violation';
    END IF;
    IF p."paymentMethod" <> 'cash' OR p."cashSessionId" IS DISTINCT FROM NEW."cashSessionId" THEN
      RAISE EXCEPTION 'Drawer movement must reference a cash payment taken on the same shift' USING ERRCODE = 'integrity_constraint_violation';
    END IF;
    IF (NEW."movementType" = 'sale' AND p.direction <> 'inbound')
       OR (NEW."movementType" = 'refund' AND (p.direction <> 'outbound' OR p."refundOfId" IS NULL))
       OR (NEW."movementType" = 'supplier_payment' AND (p.direction <> 'outbound' OR p."refundOfId" IS NOT NULL)) THEN
      RAISE EXCEPTION 'Drawer movement type % does not match its payment', NEW."movementType" USING ERRCODE = 'integrity_constraint_violation';
    END IF;
  END IF;
  IF NEW."reversalOfMovementId" IS NOT NULL AND NOT EXISTS (
    SELECT 1 FROM "CashMovement" o WHERE o.id = NEW."reversalOfMovementId" AND o."organizationId" = NEW."organizationId"
  ) THEN
    RAISE EXCEPTION 'A reversal must reference a movement of the same organization' USING ERRCODE = 'integrity_constraint_violation';
  END IF;
  IF NEW."correctionOfSessionId" IS NOT NULL AND NOT EXISTS (
    SELECT 1 FROM "CashSession" s WHERE s.id = NEW."correctionOfSessionId" AND s."organizationId" = NEW."organizationId" AND s.status <> 'open'
  ) THEN
    RAISE EXCEPTION 'A correction must reference a closed shift of the same organization' USING ERRCODE = 'integrity_constraint_violation';
  END IF;
  RETURN NEW;
END $$;


--
-- Name: guard_cash_session(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.guard_cash_session() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF evidence_purge_enabled() THEN RETURN COALESCE(NEW, OLD); END IF;
  IF TG_OP = 'DELETE' THEN
    RAISE EXCEPTION 'CashSession % cannot be deleted', OLD.id USING ERRCODE = 'integrity_constraint_violation';
  END IF;
  IF OLD.status = 'open' THEN
    IF NEW.status = 'reconciled' THEN
      RAISE EXCEPTION 'CashSession % must be closed before it is reconciled', OLD.id USING ERRCODE = 'integrity_constraint_violation';
    END IF;
    IF evidence_row_changed(to_jsonb(OLD), to_jsonb(NEW), ARRAY['status','closedAt','closingCounted','closingExpected','closingDifference','closingDenomination','closingByMethod','closingAccounts','varianceReason','varianceStatus','approvedById','bankedAmount','bankName','deviceId','notes','updatedAt']) THEN
      RAISE EXCEPTION 'Open CashSession % identity, register, drawer or float cannot change', OLD.id USING ERRCODE = 'integrity_constraint_violation';
    END IF;
    RETURN NEW;
  END IF;
  IF OLD.status = 'closed' THEN
    IF NEW.status NOT IN ('closed', 'reconciled') THEN
      RAISE EXCEPTION 'Closed CashSession % cannot be reopened; post a correction in a current shift', OLD.id USING ERRCODE = 'integrity_constraint_violation';
    END IF;
    IF evidence_row_changed(to_jsonb(OLD), to_jsonb(NEW), ARRAY['status','varianceReason','varianceStatus','approvedById','notes','updatedAt']) THEN
      RAISE EXCEPTION 'Closed CashSession % count and totals are immutable', OLD.id USING ERRCODE = 'integrity_constraint_violation';
    END IF;
    IF OLD."varianceReason" IS NOT NULL AND (NEW."varianceReason" IS NULL OR left(NEW."varianceReason", length(OLD."varianceReason")) <> OLD."varianceReason") THEN
      RAISE EXCEPTION 'The variance explanation of CashSession % can only be appended to', OLD.id USING ERRCODE = 'integrity_constraint_violation';
    END IF;
    IF OLD.notes IS NOT NULL AND (NEW.notes IS NULL OR left(NEW.notes, length(OLD.notes)) <> OLD.notes) THEN
      RAISE EXCEPTION 'The notes of closed CashSession % can only be appended to', OLD.id USING ERRCODE = 'integrity_constraint_violation';
    END IF;
    RETURN NEW;
  END IF;
  IF evidence_row_changed(to_jsonb(OLD), to_jsonb(NEW), ARRAY['updatedAt']) THEN
    RAISE EXCEPTION 'Reconciled CashSession % is final', OLD.id USING ERRCODE = 'integrity_constraint_violation';
  END IF;
  RETURN NEW;
END $$;


--
-- Name: guard_inventory_ledger(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.guard_inventory_ledger() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF evidence_purge_enabled() THEN RETURN COALESCE(NEW, OLD); END IF;
  IF TG_OP = 'UPDATE'
     AND NOT evidence_row_changed(to_jsonb(OLD), to_jsonb(NEW), ARRAY['batchId', 'serialId'])
     AND (NEW."batchId" IS NULL OR NEW."batchId" IS NOT DISTINCT FROM OLD."batchId")
     AND (NEW."serialId" IS NULL OR NEW."serialId" IS NOT DISTINCT FROM OLD."serialId") THEN
    -- Only a lot/serial reference being cleared by its FK (ON DELETE SET NULL).
    RETURN NEW;
  END IF;
  RAISE EXCEPTION 'InventoryLedger % is posted stock evidence and cannot be %; post a reversal or adjustment instead',
    OLD.id, lower(TG_OP) USING ERRCODE = 'integrity_constraint_violation';
END $$;


--
-- Name: guard_journal_entry(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.guard_journal_entry() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF evidence_purge_enabled() THEN RETURN COALESCE(NEW, OLD); END IF;
  IF OLD.status = 'draft' THEN RETURN COALESCE(NEW, OLD); END IF;
  IF TG_OP = 'DELETE' THEN
    RAISE EXCEPTION 'Posted journal entry % cannot be deleted; reverse it', OLD."entryNumber" USING ERRCODE = 'integrity_constraint_violation';
  END IF;
  IF NOT (NEW.status = OLD.status OR (OLD.status = 'posted' AND NEW.status = 'reversed')) THEN
    RAISE EXCEPTION 'Journal entry % cannot move from % to %', OLD."entryNumber", OLD.status, NEW.status USING ERRCODE = 'integrity_constraint_violation';
  END IF;
  IF evidence_row_changed(to_jsonb(OLD), to_jsonb(NEW), ARRAY['status','reversedEntryId','postingKey','updatedAt']) THEN
    RAISE EXCEPTION 'Posted journal entry % is immutable; reverse it', OLD."entryNumber" USING ERRCODE = 'integrity_constraint_violation';
  END IF;
  RETURN NEW;
END $$;


--
-- Name: guard_journal_line(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.guard_journal_line() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE entry_status text;
BEGIN
  IF evidence_purge_enabled() THEN RETURN COALESCE(NEW, OLD); END IF;
  SELECT status::text INTO entry_status FROM "JournalEntry" WHERE id = OLD."journalEntryId";
  -- NULL: the parent draft is being deleted in this statement (cascade).
  IF entry_status IS NULL OR entry_status = 'draft' THEN RETURN COALESCE(NEW, OLD); END IF;
  RAISE EXCEPTION 'Lines of posted journal entries cannot be %', lower(TG_OP) USING ERRCODE = 'integrity_constraint_violation';
END $$;


--
-- Name: guard_payment(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.guard_payment() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF evidence_purge_enabled() THEN RETURN COALESCE(NEW, OLD); END IF;
  IF TG_OP = 'DELETE' THEN
    RAISE EXCEPTION 'Payment % cannot be deleted; void it', OLD."paymentNumber" USING ERRCODE = 'integrity_constraint_violation';
  END IF;
  IF OLD."journalEntryId" IS NOT NULL AND NEW."journalEntryId" IS DISTINCT FROM OLD."journalEntryId" THEN
    RAISE EXCEPTION 'Payment % journal link is immutable', OLD."paymentNumber" USING ERRCODE = 'integrity_constraint_violation';
  END IF;
  IF OLD.status = 'cancelled' AND NEW.status <> 'cancelled' THEN
    RAISE EXCEPTION 'Voided payment % cannot be restored', OLD."paymentNumber" USING ERRCODE = 'integrity_constraint_violation';
  END IF;
  IF evidence_row_changed(to_jsonb(OLD), to_jsonb(NEW), ARRAY['status','journalEntryId','allocatedAmount','unallocatedAmount','refundedAmount','voidedAt','voidedById','voidReason','voidedAllocations','updatedAt','updatedBy']) THEN
    RAISE EXCEPTION 'Payment % amount, tender, account and drawer are immutable', OLD."paymentNumber" USING ERRCODE = 'integrity_constraint_violation';
  END IF;
  RETURN NEW;
END $$;


--
-- Name: guard_payment_allocation(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.guard_payment_allocation() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE snapshot jsonb; found_payment boolean;
BEGIN
  IF evidence_purge_enabled() THEN RETURN COALESCE(NEW, OLD); END IF;
  IF TG_OP = 'UPDATE' THEN
    IF evidence_row_changed(to_jsonb(OLD), to_jsonb(NEW), ARRAY['refundedAmount']) THEN
      RAISE EXCEPTION 'Payment allocation % is immutable', OLD.id USING ERRCODE = 'integrity_constraint_violation';
    END IF;
    RETURN NEW;
  END IF;
  SELECT "voidedAllocations", true INTO snapshot, found_payment FROM "Payment" WHERE id = OLD."paymentId";
  IF found_payment AND snapshot IS NULL THEN
    RAISE EXCEPTION 'Payment allocation % can only be released by a recorded payment void', OLD.id USING ERRCODE = 'integrity_constraint_violation';
  END IF;
  RETURN OLD;
END $$;


--
-- Name: guard_pos_refund(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.guard_pos_refund() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF evidence_purge_enabled() THEN RETURN COALESCE(NEW, OLD); END IF;
  IF TG_OP = 'DELETE' THEN
    RAISE EXCEPTION 'Refund % cannot be deleted', OLD.id USING ERRCODE = 'integrity_constraint_violation';
  END IF;
  IF OLD."journalEntryId" IS NOT NULL AND evidence_row_changed(to_jsonb(OLD), to_jsonb(NEW), ARRAY['updatedAt']) THEN
    RAISE EXCEPTION 'Posted refund % is immutable', OLD.id USING ERRCODE = 'integrity_constraint_violation';
  END IF;
  IF evidence_row_changed(to_jsonb(OLD), to_jsonb(NEW), ARRAY['payments','journalEntryId','updatedAt']) THEN
    RAISE EXCEPTION 'Refund % amount and lines are immutable', OLD.id USING ERRCODE = 'integrity_constraint_violation';
  END IF;
  RETURN NEW;
END $$;


--
-- Name: guard_write_once(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.guard_write_once() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF evidence_purge_enabled() THEN RETURN COALESCE(NEW, OLD); END IF;
  RAISE EXCEPTION '% % is write-once financial evidence', TG_TABLE_NAME, OLD.id USING ERRCODE = 'integrity_constraint_violation';
END $$;


--
-- Name: purchase_payment_not_over_po(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.purchase_payment_not_over_po() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
  po_total DECIMAL(20,6);
  paid DECIMAL(20,6);
BEGIN
  SELECT "totalAmount" INTO po_total FROM "PurchaseOrder"
   WHERE id = NEW."purchaseOrderId" AND "paymentType" = 'credit' FOR UPDATE;
  -- Cash purchases auto-settle what each receipt vouchered (which may round or
  -- over-receive); only manually paid credit POs are capped here.
  IF NOT FOUND THEN
    RETURN NULL;
  END IF;
  SELECT COALESCE(SUM(amount), 0) INTO paid FROM "PurchasePayment"
   WHERE "purchaseOrderId" = NEW."purchaseOrderId";
  IF paid > po_total + 0.000001 THEN
    RAISE EXCEPTION 'PurchasePayment total % exceeds purchase order total %', paid, po_total
      USING ERRCODE = 'check_violation';
  END IF;
  RETURN NULL;
END;
$$;


