    CONSTRAINT "CashMovement_amount_direction_check" CHECK (((("movementType" = ANY (ARRAY['sale'::public."CashMovementType", 'refund'::public."CashMovementType", 'supplier_payment'::public."CashMovementType", 'pay_in'::public."CashMovementType", 'pay_out'::public."CashMovementType"])) AND (amount > (0)::numeric)) OR (("movementType" = 'adjustment'::public."CashMovementType") AND (amount <> (0)::numeric)))),
    CONSTRAINT "CashMovement_payment_link_check" CHECK (((("movementType" = ANY (ARRAY['sale'::public."CashMovementType", 'refund'::public."CashMovementType", 'supplier_payment'::public."CashMovementType"])) AND ("paymentId" IS NOT NULL)) OR (("movementType" = ANY (ARRAY['pay_in'::public."CashMovementType", 'pay_out'::public."CashMovementType", 'adjustment'::public."CashMovementType"])) AND ("paymentId" IS NULL))))
);


